def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    # Check all possible starting positions for prefix in s
    for i in range(len(s) - len(prefix) + 1):
        if s[i:i + len(prefix)] == prefix:
            # Check if suffix can match from the current index
            if s[i + len(prefix):].startswith(suffix) or len(suffix) == 0:
                return True

    # Additionally, check if suffix fits before the end of s considering variable length of '*'
    for j in range(len(suffix) + 1):
        # Check if prefix matches the start of s
        if len(s) >= len(prefix) + j and s[:len(prefix)] == prefix:
            # Check if the remaining s can match the suffix from the end
            if s[len(s) - len(suffix) + j:] == suffix:
                return True

    return False

