def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse right
            for j in range(len(grid[i])):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse left
            for j in range(len(grid[i]) - 1, -1, -1):
                if j % 2 == 0:
                    result.append(grid[i][j])
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    count = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first = int(s[i])
            second = int(s[i + 1])
            if count[s[i]] == first and count[s[i + 1]] == second:
                return s[i] + s[i + 1]
