def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Starting point

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k represents the number of robbers neutralized
                if i == 0 and j == 0:
                    continue  # Skip the starting cell
                if i > 0:
                    current_coins = dp[i-1][j][k]
                    if coins[i][j] < 0:
                        if k > 0:
                            dp[i][j][k] = max(dp[i][j][k], current_coins + coins[i][j])  # Neutralizing robber
                        dp[i][j][k] = max(dp[i][j][k], current_coins)  # Without neutralization
                    else:
                        dp[i][j][k] = max(dp[i][j][k], current_coins + coins[i][j])
                if j > 0:
                    current_coins = dp[i][j-1][k]
                    if coins[i][j] < 0:
                        if k > 0:
                            dp[i][j][k] = max(dp[i][j][k], current_coins + coins[i][j])  # Neutralizing robber
                        dp[i][j][k] = max(dp[i][j][k], current_coins)  # Without neutralization
                    else:
                        dp[i][j][k] = max(dp[i][j][k], current_coins + coins[i][j])
                if coins[i][j] < 0 and k > 0:  # Consider the neutralization case
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1] + coins[i][j])

    return max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])

