def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(
                dp[i - 1][(j + 1) % 3],  
                dp[i - 1][(j + 2) % 3]  
            )

    min_cost = float('inf')

    # Calculate total costs considering 'equidistant houses'
    for first_color in range(3):
        for second_color in range(3):
            if first_color != second_color:
                # Compute the total cost of selecting these colors for the ends
                total_cost = dp[n - 1][first_color] + dp[n // 2][second_color]
                min_cost = min(min_cost, total_cost)

    return min_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    user_offline_until = [0] * numberOfUsers

    for event in sorted(events, key=lambda x: int(x[1])):
        event_type, timestamp, *details = event
        timestamp = int(timestamp)

        if event_type == 'OFFLINE':
            user_id = int(details[0])
            online_status[user_id] = False
            user_offline_until[user_id] = timestamp + 60

        elif event_type == 'MESSAGE':
            # Process offline users first
            for user_id in range(numberOfUsers):
                if not online_status[user_id] and timestamp >= user_offline_until[user_id]:
                    online_status[user_id] = True

            mentions_string = details[0]

            if mentions_string == 'ALL':
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            elif mentions_string == 'HERE':
                for user_id in range(numberOfUsers):
                    if online_status[user_id]:
                        mentions[user_id] += 1
            else:
                for mention in mentions_string.split():
                    if mention.startswith('id'):
                        user_id = int(mention[2:])
                        mentions[user_id] += 1

    return mentions

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    for move in s:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        elif move == 'W':
            x -= 1
        # Calculate current Manhattan distance
        current_distance = abs(x) + abs(y)
        # Update max distance
        max_distance = max(max_distance, current_distance)
    # The maximum distance can be increased by k in any direction
    return max_distance + k
